from pathlib import Path

from alembic import command
from alembic.config import Config
from sqlalchemy import create_engine, inspect

from core.config import settings


def test_upgrade_from_empty_then_downgrade_disposable_database(tmp_path, monkeypatch):
    # The path is generated by pytest; no external/development URL is ever used.
    url = f"sqlite:///{tmp_path / 'migration-test.db'}"
    monkeypatch.setattr(settings, "DATABASE_URL", url)
    config = Config(str(Path(__file__).resolve().parents[1] / "alembic.ini"))
    command.upgrade(config, "head")
    engine = create_engine(url)
    inspector = inspect(engine)
    assert {"users", "enterprises", "documents", "document_chunks"} <= set(
        inspector.get_table_names()
    )
    assert {"embedding", "embedding_model"} <= {
        c["name"] for c in inspector.get_columns("document_chunks")
    }
    engine.dispose()
    command.check(config)
    command.downgrade(config, "base")
    engine = create_engine(url)
    assert "users" not in inspect(engine).get_table_names()
    engine.dispose()
